var lv=new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l=>l.Elevation).Select(l=>l.Id.IntegerValue+" "+l.Name+" "+Math.Round(l.Elevation*304.8)).ToList();
var cats=new[]{"Doors","Windows","Parking","Plumbing Fixtures","Specialty Equipment","Generic Models","Columns","Structural Columns","Furniture","Casework","Mechanical Equipment","Vertical Circulation"};
var sy=new FilteredElementCollector(doc).OfClass(typeof(FamilySymbol)).Cast<FamilySymbol>().Where(s=>s.Category!=null&&cats.Contains(s.Category.Name)).Select(s=>{Func<string,string> g=n=>{var p=s.LookupParameter(n);return p==null?"":" "+n+"="+p.AsValueString();};return s.Id.IntegerValue+"|"+s.Category.Name+"|"+s.Family.Name+"|"+s.Name+"|"+s.Family.FamilyPlacementType+g("Width")+g("Length")+g("Depth")+g("Height");}).ToList();
var wt=new FilteredElementCollector(doc).OfClass(typeof(WallType)).Cast<WallType>().Select(w=>w.Id.IntegerValue+" "+w.Name+" "+w.Kind+" "+Math.Round(w.Width*304.8)).ToList();
var st=new FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Architecture.StairsType)).Cast<Autodesk.Revit.DB.Architecture.StairsType>().Select(s=>s.Id.IntegerValue+" "+s.Name+" maxR "+Math.Round(s.MaxRiserHeight*304.8)+" minT "+Math.Round(s.MinTreadDepth*304.8)+" minW "+Math.Round(s.MinRunWidth*304.8)).ToList();
var inst=new FilteredElementCollector(doc).WhereElementIsNotElementType().Where(e=>e.Category!=null&&e.Category.CategoryType==CategoryType.Model&&!(e is Material)).Select(e=>{var b=e.get_BoundingBox(null);return e.Id.IntegerValue+"|"+e.Category.Name+"|"+e.Name+(b==null?"":"|"+Math.Round(b.Min.X*304.8)+","+Math.Round(b.Min.Y*304.8)+","+Math.Round(b.Min.Z*304.8)+" > "+Math.Round(b.Max.X*304.8)+","+Math.Round(b.Max.Y*304.8)+","+Math.Round(b.Max.Z*304.8));}).Take(150).ToList();
var gr=new FilteredElementCollector(doc).OfClass(typeof(Grid)).Select(g=>g.Name).ToList();
var ph=doc.Phases.Cast<Phase>().Select(p=>p.Name).ToList();
return new{lv,sy,wt,st,inst,gr,ph};
